26	/// Resolve metadata directory for reads/mutations, honoring git sidecar when enabled.
27	pub fn metadata_dir_from_parts(
28	    repo_root: &Path,
29	    config_path: &Path,
30	    inline_residual_dir: &Path,
31	) -> Result<PathBuf> {
32	    let sidecar = git_sidecar::SidecarConfig::from_config_file(config_path)?;
33	    if sidecar.enabled {
34	        git_sidecar::read_sidecar_metadata(repo_root, &sidecar)
35	    } else {
36	        Ok(inline_residual_dir.to_path_buf())
37	    }
38	}
39	
40	/// Resolve metadata directory for a loaded config.
41	pub fn metadata_dir(cfg: &Config) -> Result<PathBuf> {
42	    metadata_dir_from_parts(&cfg.repo_root, &cfg.config_path, &cfg.config_host_dir)
43	}
44	
45	/// Resolve metadata directory for a mutation. Strict in branch mode: bails with a
46	/// `residual branch init` hint rather than silently falling back to trunk.
47	pub fn metadata_dir_for_mutation(cfg: &Config) -> Result<PathBuf> {
48	    let sidecar = git_sidecar::SidecarConfig::from_config_file(&cfg.config_path)?;
49	    if sidecar.enabled {
50	        git_sidecar::write_sidecar_metadata(&cfg.repo_root, &sidecar)
51	    } else {
52	        Ok(cfg.config_host_dir.clone())
53	    }
54	}
55	
56	/// Resolve metadata directory for reads/mutations, honoring git sidecar when enabled.
57	pub fn effective_metadata_dir(repo_root: &Path, config_path: &Path) -> Result<PathBuf> {
58	    let discovery = git_sidecar::discover_config(repo_root)?;
59	    metadata_dir_from_parts(repo_root, config_path, &discovery.residual_dir)
60	}
