62	/// Print resolved storage banner (S-58) to stdout.
63	pub fn print_storage_banner() -> Result<()> {
64	    let cwd = std::env::current_dir()?;
65	    let discovery = git_sidecar::discover_config(&cwd)?;
66	    let sidecar = git_sidecar::SidecarConfig::from_config_file(&discovery.config_path)?;
67	    println!(
68	        "{}",
69	        git_sidecar::format_storage_banner(&discovery, &sidecar)
70	    );
71	    Ok(())
72	}
