74	pub fn init(cfg: &Config, force: bool) -> Result<()> {
75	    write_authorization::require(cfg)?;
76	    let host = &cfg.config_host_dir;
77	    let session = integrity::sessions::begin_mutation(host, force)?;
78	    init_dirs_and_files(host)?;
79	    session.commit()?;
80	    println!("Initialized residual/ at {}", host.display());
81	    Ok(())
82	}
