84	fn init_dirs_and_files(dir: &Path) -> Result<()> {
85	    fs::create_dir_all(dir.join("iterations"))?;
86	    fs::create_dir_all(dir.join("personas"))?;
87	    fs::create_dir_all(dir.join("research"))?;
88	
89	    // Write config.toml if not present (storage-config; format_version v4 by default).
90	    let config_path = dir.join("config.toml");
91	    if !config_path.exists() {
92	        let toml =
93	            crate::storage::config::render_v3(&crate::storage::config::StorageConfig::default());
94	        fs::write(&config_path, toml)?;
95	    }
96	
97	    // Write empty CSVs with headers if not present
98	    let csvs: &[(&str, &str)] = &[
99	        (
100	            "stressors.csv",
101	            "id,shortname,description,naive_change,outcomes,attractor_id",
102	        ),
103	        (
104	            "purposes.csv",
105	            "id,shortname,description,naive_change,outcomes,attractor_id",
106	        ),
107	        (
108	            "attractors.csv",
109	            "id,name,description,positive_state,negative_state",
110	        ),
111	        ("lexicon.csv", "term,definition,domain,aliases"),
112	        ("residues.csv", "force"),
113	        ("components.csv", "name,description,status,architecture_set"),
114	    ];
115	    for (filename, header) in csvs {
116	        let path = dir.join(filename);
117	        if !path.exists() {
118	            fs::write(&path, format!("{}\n", header))?;
119	        }
120	    }
121	
122	    defense::init_tree(dir)?;
123	    Ok(())
124	}
