126	pub fn add(cfg: &Config, target: AddTarget, force: bool) -> Result<()> {
127	    write_authorization::require(cfg)?;
128	    let dir = metadata_dir_for_mutation(cfg)?;
129	    let session = integrity::sessions::begin_mutation(&dir, force)?;
130	    add_entry(&dir, target)?;
131	    session.commit()?;
132	    git_sidecar::persist_if_sidecar(cfg, &dir)?;
133	    Ok(())
134	}
