136	pub fn remove(cfg: &Config, target: RemoveTarget, force: bool) -> Result<()> {
137	    write_authorization::require(cfg)?;
138	    let dir = metadata_dir_for_mutation(cfg)?;
139	    let session = integrity::sessions::begin_mutation(&dir, force)?;
140	    remove_entry(&dir, target)?;
141	    session.commit()?;
142	    git_sidecar::persist_if_sidecar(cfg, &dir)?;
143	    Ok(())
