160	            description,
161	            attractor_id,
162	            naive_change,
163	            shortname,
164	            outcomes,
165	            add_component,
166	            remove_component,
167	        } => {
168	            stressors::update(
169	                dir,
170	                &force_id,
171	                description,
172	                attractor_id,
173	                naive_change,
174	                shortname,
175	                outcomes,
176	                add_component,
177	                remove_component,
178	            )?;
179	            println!("Updated stressor {}", force_id);
180	        }
181	        UpdateTarget::Purpose {
182	            force_id,
183	            description,
184	            attractor_id,
185	            naive_change,
186	            shortname,
187	            outcomes,
188	            add_component,
189	            remove_component,
190	        } => {
191	            purposes::update(
192	                dir,
193	                &force_id,
194	                description,
195	                attractor_id,
196	                naive_change,
197	                shortname,
198	                outcomes,
199	                add_component,
200	                remove_component,
201	            )?;
202	            println!("Updated purpose {}", force_id);
203	        }
204	        UpdateTarget::Attractor {
205	            id,
206	            name,
207	            description,
208	            positive_state,
209	            negative_state,
210	        } => {
211	            attractors::update(dir, &id, name, description, positive_state, negative_state)?;
212	            println!("Updated attractor {}", id);
213	        }
214	        UpdateTarget::Component {
215	            name,
216	            description,
217	            status,
218	            architecture_set,
219	        } => {
220	            components::update(dir, &name, description, status, architecture_set)?;
221	            println!("Updated component '{}'", name);
