245	fn remove_entry(dir: &Path, target: RemoveTarget) -> Result<()> {
246	    match target {
247	        RemoveTarget::Residue {
248	            force_id,
249	            component_id,
250	        } => {
251	            residues::remove_coupling(dir, &force_id, &component_id)?;
252	            println!("Removed residue coupling {} × {}", force_id, component_id);
253	        }
254	        RemoveTarget::Term { term } => {
255	            if terminology::remove(dir, &term)? {
256	                println!("Removed term '{term}'");
257	            } else {
258	                anyhow::bail!("term '{term}' does not exist");
259	            }
260	        }
261	    }
262	    Ok(())
263	}
