265	fn add_entry(dir: &Path, target: AddTarget) -> Result<()> {
266	    match target {
267	        AddTarget::Stressor {
268	            description,
269	            attractor_id,
270	            naive_change,
271	            shortname,
272	            outcomes,
273	            whole_system,
274	            notes,
275	        } => {
276	            let naive_change = if whole_system {
277	                if notes.is_empty() {
278	                    anyhow::bail!("--whole-system requires --notes describing the hardware, process, organization, or policy zig");
279	                }
280	                tag_naive_change_whole_system(&naive_change)
281	            } else {
282	                eprintln!("{WHOLE_SYSTEM_REMINDER}");
283	                naive_change
284	            };
285	            let existing = stressors::load(dir)?;
286	            let id = stressors::next_id(&existing);
287	            stressors::append(
288	                dir,
289	                stressors::Stressor {
290	                    id: id.clone(),
291	                    shortname,
292	                    description,
293	                    attractor_id,
294	                    naive_change,
295	                    outcomes,
296	                },
297	            )?;
298	            if whole_system {
299	                let residue_id = residues::append_whole_system(dir, &id, &notes)?;
300	                println!("Added whole-system-residue {}", residue_id);
301	            }
302	            println!("Added stressor {}", id);
303	        }
304	        AddTarget::Residue {
305	            force_id,
306	            component_id,
307	            whole_system,
308	            notes,
309	            move_to,
310	        } => {
311	            if !move_to.is_empty() {
312	                if component_id.is_empty() {
313	                    anyhow::bail!("--move-to requires --component-id (source component)");
314	                }
315	                if !residues::force_exists(dir, &force_id)? {
316	                    anyhow::bail!("force id '{}' not found in stressors or purposes", force_id);
317	                }
318	                residues::move_coupling(dir, &force_id, &component_id, &move_to)?;
319	                println!(
320	                    "Moved residue coupling {} from {} to {}",
321	                    force_id, component_id, move_to
322	                );
323	            } else if whole_system {
324	                let id = residues::append_whole_system(dir, &force_id, &notes)?;
325	                println!("Added whole-system-residue {}", id);
326	            } else {
327	                if component_id.is_empty() {
328	                    anyhow::bail!("provide --component-id or --whole-system");
329	                }
330	                if !residues::force_exists(dir, &force_id)? {
331	                    anyhow::bail!("force id '{}' not found in stressors or purposes", force_id);
332	                }
333	                let existing = residues::load(dir)?;
334	                let id = residues::next_id(&existing);
335	                residues::append(dir, Residue::coupling(id.clone(), force_id, component_id))?;
336	                println!("Added residue coupling {}", id);
337	            }
338	        }
339	        AddTarget::Component {
340	            name,
341	            description,
342	            status,
343	            architecture_set,
344	        } => {
345	            let added = components::append_idempotent_inner(
346	                dir,
347	                &name,
348	                &description,
349	                &status,
350	                &architecture_set,
351	            )?;
352	            if added {
353	                println!("Added component '{}'", name);
354	            } else {
355	                // Promote / update status when the registry row already exists (P-30 hygiene).
356	                components::set_status_inner(dir, &name, &status)?;
357	                println!("Updated component '{}' status to '{}'", name, status);
358	            }
359	        }
360	        AddTarget::Purpose {
361	            description,
362	            attractor_id,
363	            naive_change,
364	            shortname,
365	            outcomes,
366	        } => {
367	            let existing = purposes::load(dir)?;
368	            let id = purposes::next_id(&existing);
369	            purposes::append(
370	                dir,
371	                purposes::Purpose {
372	                    id: id.clone(),
373	                    shortname,
374	                    description,
375	                    attractor_id,
376	                    naive_change,
377	                    outcomes,
378	                },
379	            )?;
380	            println!("Added purpose {}", id);
381	        }
382	        AddTarget::Attractor {
383	            name,
384	            description,
385	            positive_state,
386	            negative_state,
387	        } => {
388	            let existing = attractors::load(dir)?;
389	            let id = attractors::next_id(&existing);
390	            attractors::append(
391	                dir,
392	                attractors::Attractor {
393	                    id: id.clone(),
394	                    name,
395	                    description,
396	                    positive_state,
397	                    negative_state,
398	                },
399	            )?;
400	            println!("Added attractor {}", id);
401	        }
402	        AddTarget::Term {
403	            term,
404	            definition,
405	            domain,
406	            related,
407	        } => {
408	            format::append_lexicon(
409	                dir,
410	                crate::structure::definition::lexicon::Term {
411	                    term: term.clone(),
412	                    definition,
413	                    domain,
414	                    aliases: related,
415	                },
416	            )?;
417	            println!("Added term '{}'", term);
418	        }
419	        AddTarget::Persona {
420	            name,
421	            role,
422	            concerns,
423	            desires,
424	        } => {
425	            personas::create(
426	                dir,
427	                personas::Persona {
428	                    name: name.clone(),
429	                    role,
430	                    concerns,
431	                    desires,
432	                    stressor_ids: vec![],
433	                },
434	            )?;
435	            println!("Added persona '{}'", name);
436	        }
437	        AddTarget::Iteration { notes, ri_score } => {
438	            let n = iterations::next_n(dir)?;
439	            let date = chrono::Local::now().format("%Y-%m-%d").to_string();
440	            iterations::create(
441	                dir,
442	                iterations::IterationMeta {
443	                    n,
444	                    date,
445	                    ri_score,
446	                    n_val: String::new(),
447	                    k_val: String::new(),
448	                    p_val: String::new(),
449	                    notes,
450	                },
451	            )?;
452	            println!("Added iteration {}", n);
453	        }
454	        AddTarget::MetaStressor {
455	            description,
456	            shortname,
457	        } => {
458	            let existing = defense::meta_stressors::load(dir)?;
459	            let id = defense::meta_stressors::next_id(&existing);
460	            defense::meta_stressors::append(
461	                dir,
462	                defense::meta_stressors::MetaStressor {
463	                    id: id.clone(),
464	                    shortname,
465	                    description,
466	                },
467	            )?;
468	            println!("Added meta-stressor {}", id);
469	        }
470	        AddTarget::MetaAttractor {
471	            name,
472	            description,
473	            positive_state,
474	            negative_state,
475	        } => {
476	            let existing = defense::meta_attractors::load(dir)?;
477	            let id = defense::meta_attractors::next_id(&existing);
478	            defense::meta_attractors::append(
479	                dir,
480	                defense::meta_attractors::MetaAttractor {
481	                    id: id.clone(),
482	                    name,
483	                    description,
484	                    positive_state,
485	                    negative_state,
486	                },
487	            )?;
488	            println!("Added meta-attractor {}", id);
489	        }
490	        AddTarget::MetaPurpose {
491	            description,
492	            attractor_id,
493	            naive_change,
494	            shortname,
495	            outcomes,
496	        } => {
497	            let existing = defense::meta_purposes::load(dir)?;
498	            let id = defense::meta_purposes::next_id(&existing);
499	            defense::meta_purposes::append(
500	                dir,
501	                defense::meta_purposes::MetaPurpose {
502	                    id: id.clone(),
503	                    shortname,
504	                    description,
505	                    naive_change,
506	                    outcomes,
507	                    attractor_id,
508	                },
509	            )?;
510	            println!("Added meta-purpose {}", id);
511	        }
512	        AddTarget::DefensePersona { name, body } => {
513	            let path = defense::artifacts::write_persona(dir, &name, &body)?;
514	            println!("Added defense-persona '{}' → {}", name, path.display());
515	        }
516	        AddTarget::DefenseStrategy { name, body } => {
517	            let path = defense::artifacts::write_strategy(dir, &name, &body)?;
518	            println!("Added defense-strategy '{}' → {}", name, path.display());
519	        }
520	        AddTarget::DefenseProgress { name, body } => {
521	            let path = defense::artifacts::write_progress(dir, &name, &body)?;
522	            println!("Added defense-progress '{}' → {}", name, path.display());
523	        }
524	        AddTarget::DefensePitch { name, body } => {
525	            let path = defense::artifacts::write_pitch(dir, &name, &body)?;
526	            println!("Added defense-pitch '{}' → {}", name, path.display());
527	        }
528	    }
529	    Ok(())
530	}
