532	pub fn list(cfg: &Config, target: ListTarget) -> Result<()> {
533	    let dir = metadata_dir(cfg)?;
534	    match target {
535	        ListTarget::Stressors => {
536	            let items = stressors::load(&dir)?;
537	            if items.is_empty() {
538	                println!("No stressors.");
539	            } else {
540	                for s in &items {
541	                    println!(
542	                        "[{}] {} {} (attractor: {})",
543	                        s.id, s.shortname, s.description, s.attractor_id
544	                    );
545	                }
546	            }
547	        }
548	        ListTarget::Purposes => {
549	            let items = purposes::load(&dir)?;
550	            if items.is_empty() {
551	                println!("No purposes.");
552	            } else {
553	                for p in &items {
554	                    let extra = if p.outcomes.is_empty() {
555	                        String::new()
556	                    } else {
557	                        format!(" | outcomes: {}", p.outcomes)
558	                    };
559	                    println!(
560	                        "[{}] {} {} (naive_change: {}{})",
561	                        p.id, p.shortname, p.description, p.naive_change, extra
562	                    );
563	                }
564	            }
565	        }
566	        ListTarget::Attractors => {
567	            let items = attractors::load(&dir)?;
568	            if items.is_empty() {
569	                println!("No attractors.");
570	            } else {
571	                for a in &items {
572	                    println!(
573	                        "[{}] {} (+/{} | -/{} )",
574	                        a.id,
575	                        a.name,
576	                        truncate_state(&a.positive_state),
577	                        truncate_state(&a.negative_state)
578	                    );
579	                }
580	            }
581	        }
582	        ListTarget::Terminology => {
583	            let items = format::read_lexicon(&dir)?;
584	            if items.is_empty() {
585	                println!("No terminology.");
586	            } else {
587	                for t in &items {
588	                    println!("{}: {}", t.term, t.definition);
