628	                println!("No meta-stressors.");
629	            } else {
630	                for s in &items {
631	                    println!("[{}] {} {}", s.id, s.shortname, s.description);
632	                }
633	            }
634	        }
635	        ListTarget::MetaAttractors => {
636	            let items = defense::meta_attractors::list(&dir)?;
637	            if items.is_empty() {
638	                println!("No meta-attractors.");
639	            } else {
640	                for a in &items {
641	                    println!("[{}] {} {}", a.id, a.name, a.description);
