643	            }
644	        }
645	        ListTarget::MetaPurposes => {
646	            let items = defense::meta_purposes::list(&dir)?;
647	            if items.is_empty() {
648	                println!("No meta-purposes.");
649	            } else {
650	                for p in &items {
651	                    println!(
652	                        "[{}] {} {} (attractor: {})",
653	                        p.id, p.shortname, p.description, p.attractor_id
654	                    );
655	                }
656	            }
657	        }
658	        ListTarget::DefensePersonas => {
659	            let names = defense::artifacts::list_personas(&dir)?;
660	            if names.is_empty() {
661	                println!("No defense-personas.");
662	            } else {
663	                for name in &names {
664	                    println!("{}", name);
665	                }
666	            }
667	        }
668	        ListTarget::DefenseStrategies => {
669	            let names = defense::artifacts::list_strategies(&dir)?;
670	            if names.is_empty() {
671	                println!("No defense-strategies.");
672	            } else {
673	                for name in &names {
674	                    println!("{}", name);
675	                }
676	            }
677	        }
678	        ListTarget::DefenseProgress => {
679	            let names = defense::artifacts::list_progress(&dir)?;
680	            if names.is_empty() {
681	                println!("No defense-progress.");
682	            } else {
683	                for name in &names {
684	                    println!("{}", name);
