10	fn write_all(residual_dir: &Path, rows: &[Component]) -> Result<()> {
11	    let mut buf = format!("{HEADER}\n");
12	    for c in rows {
13	        let mut row = Vec::new();
14	        {
15	            let mut wtr = csv::WriterBuilder::new().has_headers(false).from_writer(&mut row);
16	            wtr.write_record(&[
17	                &c.name,
18	                &c.description,
19	                &c.status,
20	                &c.architecture_set,
21	            ])?;
22	            wtr.flush()?;
23	        }
24	        buf.push_str(std::str::from_utf8(&row)?);
25	    }
26	    std::fs::write(residual_dir.join("components.csv"), buf)?;
