5	pub struct TermIndex {
6	    pub words: std::collections::HashSet<String>,
7	    pub phrases: Vec<String>,
8	}
9	
10	fn add_index_tokens(
11	    words: &mut std::collections::HashSet<String>,
12	    phrases: &mut Vec<String>,
13	    raw: &str,
14	) {
15	    let trimmed = raw.trim().to_lowercase();
16	    if trimmed.is_empty() {
17	        return;
18	    }
19	    phrases.push(trimmed.clone());
20	    words.insert(trimmed.clone());
21	    for token in trimmed.split_whitespace() {
22	        if !token.is_empty() {
23	            words.insert(token.to_string());
24	        }
25	    }
26	}
27	
28	pub fn term_index(residual_dir: &Path) -> Result<TermIndex> {
29	    let mut words = std::collections::HashSet::new();
30	    let mut phrases = Vec::new();
31	
32	    for t in crate::storage::format::read_lexicon(residual_dir)? {
33	        add_index_tokens(&mut words, &mut phrases, &t.term);
34	        for alias in t.aliases.split('|') {
35	            add_index_tokens(&mut words, &mut phrases, alias);
36	        }
37	    }
38	
39	    phrases.sort_by_key(|p| std::cmp::Reverse(p.len()));
40	    phrases.dedup();
41	
42	    Ok(TermIndex { words, phrases })
43	}
