90	fn parse_persona(content: &str, name: String) -> Persona {
91	    let mut role = String::new();
92	    let mut concerns = String::new();
93	    let mut desires = String::new();
94	    let mut stressor_ids = Vec::new();
95	
96	    // Extract front-matter between --- delimiters
97	    let inner = if content.starts_with("---") {
98	        let after = &content[3..];
99	        if let Some(end) = after.find("---") {
100	            &after[..end]
101	        } else {
102	            ""
103	        }
104	    } else {
105	        ""
106	    };
107	
108	    let mut in_stressor_ids = false;
109	    for line in inner.lines() {
110	        let trimmed = line.trim();
111	        if let Some(rest) = trimmed.strip_prefix("role:") {
112	            role = rest.trim().trim_matches('"').to_string();
113	            in_stressor_ids = false;
114	        } else if let Some(rest) = trimmed.strip_prefix("concerns:") {
115	            concerns = rest.trim().trim_matches('"').to_string();
116	            in_stressor_ids = false;
117	        } else if let Some(rest) = trimmed.strip_prefix("desires:") {
118	            desires = rest.trim().trim_matches('"').to_string();
119	            in_stressor_ids = false;
120	        } else if trimmed.starts_with("stressor_ids:") {
121	            in_stressor_ids = true;
122	        } else if in_stressor_ids && trimmed.starts_with("- ") {
123	            let id = trimmed[2..].trim().trim_matches('"').to_string();
124	            if !id.is_empty() {
125	                stressor_ids.push(id);
126	            }
127	        } else if !trimmed.is_empty() && !trimmed.starts_with('-') {
128	            in_stressor_ids = false;
129	        }
130	    }
131	
132	    Persona { name, role, concerns, desires, stressor_ids }
133	}
